python -c "
from databricks.sdk import WorkspaceClient
w = WorkspaceClient()
# Existing clusters
try:
    cls = list(w.clusters.list())
    print('CLUSTERS:', [(c.cluster_name, c.cluster_id, str(c.state)) for c in cls][:10])
except Exception as e:
    print('clusters err', e)
print('--- node types (smallest) ---')
try:
    nt = w.clusters.list_node_types()
    small = sorted([n for n in nt.node_types if n.num_cores], key=lambda n:(n.num_cores, n.memory_mb))[:3]
    for n in small: print(n.node_type_id, n.num_cores, n.memory_mb)
except Exception as e:
    print('nt err', e)
print('--- spark versions ---')
try:
    sv = w.clusters.spark_versions()
    for s in sv.versions:
        if 'LTS' in (s.name or '') and 'ML' not in (s.name or '') and 'GPU' not in (s.name or ''):
            print(s.key, s.name)
except Exception as e:
    print('sv err', e)
"
